//! CPU kernels for the valid-aware depth median and the flying-pixel mask.
//!
//! Invalid samples are mapped to a sort key above every valid key (see
//! [`DepthRepr::key`]), the window is fully sorted by a Batcher odd-even
//! merge network ([`SORT9`] / [`SORT25`]) and the median of the `n` valid
//! samples is read at index `n / 2`. The network is generated by a `const fn`
//! and the CUDA kernels in `cuda/depth.rs` are code-generated from the same
//! arrays, so the two sides run the identical compare-exchange sequence.

use rayon::prelude::*;

/// Number of output pixels processed together; the compare-exchanges run
/// lane-wise on `[K; LANES]` arrays so the compiler can vectorize them.
pub(crate) const LANES: usize = 8;

/// Window side of the flying-pixel test.
pub(crate) const FLYING_KSIZE: usize = 3;

/// Value written to the mask for a flagged pixel.
pub(crate) const MASK_FLAGGED: u8 = 255;

/// Number of compare-exchanges of Batcher's odd-even merge sort on `n` wires.
const fn batcher_len(n: usize) -> usize {
    let mut count = 0;
    let mut p = 1;
    while p < n {
        let mut k = p;
        while k >= 1 {
            let mut j = k % p;
            while j + k < n {
                let mut i = 0;
                while i < k && i + j + k < n {
                    if (i + j) / (p * 2) == (i + j + k) / (p * 2) {
                        count += 1;
                    }
                    i += 1;
                }
                j += 2 * k;
            }
            k /= 2;
        }
        p *= 2;
    }
    count
}

/// Batcher's odd-even merge sort on `n` wires (Knuth, TAOCP vol. 3, 5.3.4),
/// with every comparator that touches a wire `>= n` of the next power of two
/// dropped. Each pair is `(a, b)` with `a < b`; after the exchange
/// `v[a] <= v[b]`.
const fn batcher<const M: usize>(n: usize) -> [(usize, usize); M] {
    let mut net = [(0usize, 0usize); M];
    let mut count = 0;
    let mut p = 1;
    while p < n {
        let mut k = p;
        while k >= 1 {
            let mut j = k % p;
            while j + k < n {
                let mut i = 0;
                while i < k && i + j + k < n {
                    if (i + j) / (p * 2) == (i + j + k) / (p * 2) {
                        net[count] = (i + j, i + j + k);
                        count += 1;
                    }
                    i += 1;
                }
                j += 2 * k;
            }
            k /= 2;
        }
        p *= 2;
    }
    net
}

/// Full sorting network for a 3×3 window.
pub(crate) const SORT9: [(usize, usize); batcher_len(9)] = batcher(9);

/// Full sorting network for a 5×5 window.
pub(crate) const SORT25: [(usize, usize); batcher_len(25)] = batcher(25);

/// Per-dtype depth semantics: which value marks a missing measurement and
/// how samples map to an order-preserving sort key in which invalid samples
/// sort after every valid one.
pub(crate) trait DepthRepr: Copy + Send + Sync + 'static {
    /// Order-preserving sort key.
    type Key: Copy + Send + Sync;
    /// The value that marks a missing measurement.
    const INVALID: Self;
    /// True when the sample is a measurement.
    fn is_valid(self) -> bool;
    /// Sort key; invalid samples map to the largest key.
    fn key(self) -> Self::Key;
    /// Inverse of [`Self::key`] for valid samples.
    fn from_key(k: Self::Key) -> Self;
    /// Smaller of two keys.
    fn kmin(a: Self::Key, b: Self::Key) -> Self::Key;
    /// Larger of two keys.
    fn kmax(a: Self::Key, b: Self::Key) -> Self::Key;
    /// `|a - b|` in `f32`, for two valid samples.
    fn abs_diff_f32(a: Self, b: Self) -> f32;
    /// The sample as `f32`.
    fn as_f32(self) -> f32;
}

impl DepthRepr for u16 {
    type Key = u16;
    const INVALID: u16 = 0;
    #[inline(always)]
    fn is_valid(self) -> bool {
        self != 0
    }
    // 0 -> u16::MAX, 1..=65535 -> 0..=65534: order-preserving on valid
    // values, and the invalid marker becomes the unique largest key.
    #[inline(always)]
    fn key(self) -> u16 {
        self.wrapping_sub(1)
    }
    #[inline(always)]
    fn from_key(k: u16) -> u16 {
        k.wrapping_add(1)
    }
    #[inline(always)]
    fn kmin(a: u16, b: u16) -> u16 {
        a.min(b)
    }
    #[inline(always)]
    fn kmax(a: u16, b: u16) -> u16 {
        a.max(b)
    }
    #[inline(always)]
    fn abs_diff_f32(a: u16, b: u16) -> f32 {
        f32::from(a.abs_diff(b))
    }
    #[inline(always)]
    fn as_f32(self) -> f32 {
        f32::from(self)
    }
}

impl DepthRepr for f32 {
    type Key = f32;
    const INVALID: f32 = f32::NAN;
    #[inline(always)]
    fn is_valid(self) -> bool {
        !self.is_nan()
    }
    // NaN -> +inf. A valid +inf ties with the sentinel, which cannot change
    // the value read at a rank below the valid count.
    #[inline(always)]
    fn key(self) -> f32 {
        if self.is_nan() {
            f32::INFINITY
        } else {
            self
        }
    }
    #[inline(always)]
    fn from_key(k: f32) -> f32 {
        k
    }
    #[inline(always)]
    fn kmin(a: f32, b: f32) -> f32 {
        a.min(b)
    }
    #[inline(always)]
    fn kmax(a: f32, b: f32) -> f32 {
        a.max(b)
    }
    #[inline(always)]
    fn abs_diff_f32(a: f32, b: f32) -> f32 {
        (a - b).abs()
    }
    #[inline(always)]
    fn as_f32(self) -> f32 {
        self
    }
}

/// Valid-sample medians of `LANES` consecutive output pixels.
struct LaneMedians<T: DepthRepr> {
    /// Median of the valid samples; meaningful only where `count > 0`.
    median: [T; LANES],
    /// Number of valid samples in the window (replicated taps counted).
    count: [u8; LANES],
}

/// Median of the valid samples in the `ksize × ksize` windows centred on
/// `(x0 + l, y)` for `l in 0..LANES`, channel `c`, replicate borders. Lanes
/// past the right edge are clamped to the last column (callers ignore them).
#[inline(always)]
fn lane_medians<T: DepthRepr, const C: usize>(
    src: &[T],
    w: usize,
    sy: &[usize; 5],
    x0: usize,
    c: usize,
    ksize: usize,
) -> LaneMedians<T> {
    let r = (ksize / 2) as isize;
    let fill = T::INVALID.key();
    let mut win = [[fill; LANES]; 25];
    let mut count = [0u8; LANES];
    let mut t = 0;
    for &row in sy.iter().take(ksize) {
        let base = row * w;
        for dx in -r..=r {
            for l in 0..LANES {
                let x = ((x0 + l) as isize + dx).clamp(0, w as isize - 1) as usize;
                let v = src[(base + x) * C + c];
                count[l] += u8::from(v.is_valid());
                win[t][l] = v.key();
            }
            t += 1;
        }
    }
    let net: &[(usize, usize)] = if ksize == 3 { &SORT9 } else { &SORT25 };
    for &(a, b) in net {
        let (lo, hi) = (win[a], win[b]);
        for l in 0..LANES {
            win[a][l] = T::kmin(lo[l], hi[l]);
            win[b][l] = T::kmax(lo[l], hi[l]);
        }
    }
    let mut median = [T::INVALID; LANES];
    for l in 0..LANES {
        median[l] = T::from_key(win[usize::from(count[l]) / 2][l]);
    }
    LaneMedians { median, count }
}

/// Source row indices of the window around `y`, replicate border.
#[inline(always)]
fn window_rows(y: usize, h: usize, ksize: usize) -> [usize; 5] {
    let r = (ksize / 2) as isize;
    let mut sy = [0usize; 5];
    for (i, dy) in (-r..=r).enumerate() {
        sy[i] = (y as isize + dy).clamp(0, h as isize - 1) as usize;
    }
    sy
}

/// Minimum rows per rayon task.
fn min_rows(h: usize) -> usize {
    h.div_ceil(rayon::current_num_threads() * 4).max(16)
}

/// Valid-aware median blur over an interleaved `h × w × C` buffer. `ksize`
/// is 3 or 5 (validated by the caller).
pub(crate) fn median_blur_depth<T: DepthRepr, const C: usize>(
    src: &[T],
    dst: &mut [T],
    w: usize,
    h: usize,
    ksize: usize,
) {
    dst.par_chunks_mut(w * C)
        .enumerate()
        .with_min_len(min_rows(h))
        .for_each(|(y, drow)| {
            let sy = window_rows(y, h, ksize);
            for x0 in (0..w).step_by(LANES) {
                let lanes = LANES.min(w - x0);
                for c in 0..C {
                    let m = lane_medians::<T, C>(src, w, &sy, x0, c, ksize);
                    for l in 0..lanes {
                        drow[(x0 + l) * C + c] = if m.count[l] == 0 {
                            T::INVALID
                        } else {
                            m.median[l]
                        };
                    }
                }
            }
        });
}

/// Flying-pixel mask over a single-channel `h × w` buffer.
pub(crate) fn flying_pixel_mask<T: DepthRepr>(
    src: &[T],
    mask: &mut [u8],
    w: usize,
    h: usize,
    abs_threshold: f32,
    rel_threshold: f32,
    min_valid: usize,
) {
    mask.par_chunks_mut(w)
        .enumerate()
        .with_min_len(min_rows(h))
        .for_each(|(y, mrow)| {
            let sy = window_rows(y, h, FLYING_KSIZE);
            for x0 in (0..w).step_by(LANES) {
                let lanes = LANES.min(w - x0);
                let m = lane_medians::<T, 1>(src, w, &sy, x0, 0, FLYING_KSIZE);
                for l in 0..lanes {
                    let d = src[y * w + x0 + l];
                    mrow[x0 + l] = if is_flying(
                        d,
                        m.median[l],
                        m.count[l],
                        abs_threshold,
                        rel_threshold,
                        min_valid,
                    ) {
                        MASK_FLAGGED
                    } else {
                        0
                    };
                }
            }
        });
}

/// The flying-pixel rule for one pixel: valid and either supported by fewer
/// than `min_valid` valid window samples, or farther than
/// `max(abs_threshold, rel_threshold * d)` from the valid-sample median.
/// Mirrored expression-for-expression by the CUDA kernel.
#[inline(always)]
fn is_flying<T: DepthRepr>(
    d: T,
    median: T,
    count: u8,
    abs_threshold: f32,
    rel_threshold: f32,
    min_valid: usize,
) -> bool {
    if !d.is_valid() {
        return false;
    }
    if usize::from(count) < min_valid {
        return true;
    }
    let threshold = abs_threshold.max(rel_threshold * d.as_f32());
    T::abs_diff_f32(d, median) > threshold
}

/// `dst = INVALID` where `mask != 0`, else `src`.
pub(crate) fn remove_flagged<T: DepthRepr>(src: &[T], mask: &[u8], dst: &mut [T]) {
    dst.par_iter_mut()
        .zip(src.par_iter().zip(mask.par_iter()))
        .with_min_len(1 << 14)
        .for_each(|(d, (&s, &m))| *d = if m != 0 { T::INVALID } else { s });
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Run `net` on 64 0/1 inputs at once (bit `j` of `wires[i]` is wire
    /// `i` of input `j`) and check every column comes out sorted.
    fn sorts_all_zero_one_inputs(net: &[(usize, usize)], n: usize) {
        let total: u64 = 1 << n;
        let mut base = 0u64;
        while base < total {
            let mut wires = vec![0u64; n];
            for (i, wire) in wires.iter_mut().enumerate() {
                for j in 0..64u64.min(total - base) {
                    if ((base + j) >> i) & 1 == 1 {
                        *wire |= 1 << j;
                    }
                }
            }
            for &(a, b) in net {
                let (lo, hi) = (wires[a] & wires[b], wires[a] | wires[b]);
                wires[a] = lo;
                wires[b] = hi;
            }
            for i in 1..n {
                // Sorted ascending: a 1 on wire i-1 implies a 1 on wire i.
                assert_eq!(wires[i - 1] & !wires[i], 0, "n={n} base={base}");
            }
            base += 64;
        }
    }

    /// Zero-one principle (Knuth 5.3.4): a comparator network that sorts
    /// every 0/1 input sorts every input.
    #[test]
    fn batcher_networks_sort_all_inputs() {
        assert!(SORT9.iter().all(|&(a, b)| a < b && b < 9));
        assert!(SORT25.iter().all(|&(a, b)| a < b && b < 25));
        sorts_all_zero_one_inputs(&SORT9, 9);
        sorts_all_zero_one_inputs(&SORT25, 25);
    }

    #[test]
    fn u16_key_is_order_preserving_with_invalid_last() {
        for v in [1u16, 2, 1000, 65534, 65535] {
            assert!(v.key() < 0u16.key());
            assert_eq!(u16::from_key(v.key()), v);
        }
        assert!(1u16.key() < 2u16.key() && 65534u16.key() < 65535u16.key());
    }
}
